public class RowSumsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("rowSums({{1,2,3},{10},{4,5}})", "[6, 10, 9]",
                java.util.Arrays.toString(RowSums.rowSums(new int[][]{{1, 2, 3}, {10}, {4, 5}})));
        check("rowSums({{5}})", "[5]",
                java.util.Arrays.toString(RowSums.rowSums(new int[][]{{5}})));
        check("rowSums(empty grid)", "[]",
                java.util.Arrays.toString(RowSums.rowSums(new int[0][0])));
        check("rowSums({{},{7}}) with an empty row", "[0, 7]",
                java.util.Arrays.toString(RowSums.rowSums(new int[][]{{}, {7}})));
        check("rowSums with negatives", "[-3, 3]",
                java.util.Arrays.toString(RowSums.rowSums(new int[][]{{-1, -2}, {1, 2}})));
        check("rowSums({{1,2,3,4,5}})", "[15]",
                java.util.Arrays.toString(RowSums.rowSums(new int[][]{{1, 2, 3, 4, 5}})));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
