public class RowSums {

    public static int[] rowSums(int[][] grid) {
        int[] sums = new int[grid.length];
        for (int row = 0; row < grid.length; row++) {
            int total = 0;
            for (int col = 0; col < grid[row].length; col++) {
                total += grid[row][col];
            }
            sums[row] = total;
        }
        return sums;
    }
}
